<script lang="ts">
  import type {FieldDefinition} from '../../api/domain';
  import {fieldRules,optionDetails} from '../../util/formRules';
  let {fields,moduleName,onConfigure}:{fields:FieldDefinition[];moduleName:string;onConfigure:(field:FieldDefinition)=>void}=$props();
  let selected=$state('');
  const active=$derived(fields.filter(f=>f.active));
  const target=$derived(active.find(f=>f.uid===selected));
</script>
<section class="panel rules-admin" aria-label="Form rules configuration"><div class="panel-heading"><div><p class="eyebrow">Module · {moduleName}</p><h2>Form rules</h2><p class="muted">Conditional fields, dependent options, exclusive choices and automatic values. Configure a field, then test the choices in a new record.</p></div></div><div class="rule-picker"><label>Field to configure<select bind:value={selected}><option value="">Choose field…</option>{#each active as field}<option value={field.uid}>{field.label} · {field.field_type}</option>{/each}</select></label><button type="button" class="button primary" disabled={!target} onclick={()=>target&&onConfigure(target)}>Configure form rules</button></div>{#each active.filter(f=>Object.keys(fieldRules(f)).length||optionDetails(f).length||f.config.presentation&&f.config.presentation!=='select') as field}<div class="configured-rule"><span><strong>{field.label}</strong><small>{[fieldRules(field).visible_when?'Conditional visibility':'',fieldRules(field).enabled_when?'Conditional editing':'',fieldRules(field).required_when?'Conditional requirement':'',fieldRules(field).exclusive_group?`Group: ${fieldRules(field).exclusive_group}`:'',optionDetails(field).length?'Option rules / values':''].filter(Boolean).join(' · ')||'Choice appearance'}</small></span><button type="button" class="button small" aria-label={`Configure rules for ${field.label}`} onclick={()=>onConfigure(field)}>Edit rules</button></div>{/each}</section>
<style>.rules-admin{margin-bottom:1rem}.rule-picker{display:flex;gap:.75rem;align-items:end;flex-wrap:wrap}.rule-picker label{display:grid;gap:.35rem;min-width:0;flex:1;max-width:28rem}.configured-rule{display:flex;gap:.75rem;justify-content:space-between;align-items:center;border-top:1px solid var(--line);margin-top:.75rem;padding-top:.75rem}.configured-rule span{min-width:0}.configured-rule small{display:block;color:var(--muted);margin-top:.25rem;overflow-wrap:anywhere}@media(max-width:540px){.rule-picker label{flex-basis:100%}.configured-rule{align-items:start}.configured-rule button{flex-shrink:0}}</style>
